const assertDamagesCovered = (policy: Policy, incident: Incident): void => {
  const uncovered = incident.damages.find(
    (damage) => !policy.items.some((item) => item.type === damage.itemType),
  );
  if (uncovered) {
    throw new Error(`item not covered by policy: ${uncovered.itemType}`);
  }
};

and reshaped the claim branch of `runScenario` to hoist the policy lookup into a local, then validate, then settle:

  if (step.op === "claim") {
